                    {internship.duration && (
                        <span className="flex items-center gap-1"><Clock size={11} /> {internship.duration}</span>
                    )}
                    {deadline && (
                        <span className={`flex items-center gap-1 ${isExpiring ? "text-red-500 font-bold" : ""}`}>
                            <Calendar size={11} /> {deadline.toLocaleDateString()}
