                    )}
                </div>

                {/* Skills */}
                {skillList.length > 0 && (
                    <div className="flex flex-wrap gap-1 mb-4">
                        {skillList.map((s) => (
                            <span key={s} className="px-2 py-0.5 bg-(--surface-2) rounded-lg text-[11px] font-medium">
