                    transition={{ type: "spring", stiffness: 400, damping: 30 }}
                  />
                )}
                {filter.label}
                {isActive && <X className="h-3 w-3" />}
              </motion.button>
            )
          })}
        </LayoutGroup>
      </div>
    </div>
  )
}

